effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 base = texture2DCv(inputImg.texture, uv);
base.r += warmth * 0.2;
base.b -= warmth * 0.1;
float dist = distance(uv, vec2(0.5));
float flare = smoothstep(0.8, 0.0, dist) * washout;
base.rgb += tint.rgb * flare;
gl_FragColor = clamp(base, 0.0, 1.0);
}
